#include <calibration/model.hpp>
#include <algorithm>
#include <array>
#include <cmath>
#include <vector>
#include <calibration/camera_parameters.hpp>
#include <calibration/geometry3d.hpp>
#include <calibration/hand_eye/linear.hpp>
#include <calibration/hand_eye/residual.hpp>
#include <calibration/solver/backend.hpp>
#include <core/exception.hpp>
namespace mv::calibration { namespace {
std::vector<double> values(const Pose3d&p){auto q=normalize_quaternion(p.rotation);return {p.translation.x,p.translation.y,p.translation.z,q.w,q.x,q.y,q.z};}
Pose3d pose_of(const solver::ParameterBlock&p){return {{p.values[0],p.values[1],p.values[2]},normalize_quaternion({p.values[3],p.values[4],p.values[5],p.values[6]})};}
Pose3d average_pose(const std::vector<Pose3d>&ps){Point3d t{};Quaterniond q{};if(ps.empty())throw core::Exception(core::Status::InvalidState,"average_pose","empty pose list");auto ref=normalize_quaternion(ps.front().rotation);double sw=0,sx=0,sy=0,sz=0;for(const auto&p:ps){t.x+=p.translation.x;t.y+=p.translation.y;t.z+=p.translation.z;auto qi=normalize_quaternion(p.rotation);double dot=ref.w*qi.w+ref.x*qi.x+ref.y*qi.y+ref.z*qi.z;if(dot<0){qi.w=-qi.w;qi.x=-qi.x;qi.y=-qi.y;qi.z=-qi.z;}sw+=qi.w;sx+=qi.x;sy+=qi.y;sz+=qi.z;}double n=static_cast<double>(ps.size());t.x/=n;t.y/=n;t.z/=n;q=normalize_quaternion({sw,sx,sy,sz});return {t,q};}
double rot_error(const Pose3d&e){auto q=normalize_quaternion(e.rotation);return 2*std::acos(std::clamp(q.w,-1.0,1.0));}
}
void calibrate_hand_eye(CalibrationDataModel& data,std::string_view method,std::array<double,4>* errors){if(!errors)throw core::Exception(core::Status::InvalidArgument,"calibrate_hand_eye","errors must not be null");if(data.setup_kind()==SetupKind::CalibrationObject)throw core::Exception(core::Status::InvalidState,"calibrate_hand_eye","hand-eye setup required");if(method!="linear"&&method!="nonlinear")throw core::Exception(core::Status::Unsupported,"calibrate_hand_eye","method must be linear or nonlinear");if(data.num_cameras()!=1||data.setup_kind()==SetupKind::HandEyeScaraMovingCamera||data.setup_kind()==SetupKind::HandEyeScaraStationaryCamera)throw core::Exception(core::Status::Unsupported,"calibrate_hand_eye","SCARA and sensor-only solving are not implemented");const auto&cam=data.camera(0);if(cam.parameters&&!is_perspective(*cam.parameters))throw core::Exception(core::Status::Unsupported,"calibrate_hand_eye","automatic hand-eye observation poses require perspective camera");
 struct Pair{std::int64_t idx;Pose3d t,c;};std::vector<Pair>pairs;for(const auto&[key,obs]:data.observations()){if(key.camera_index!=0||!obs.initial_pose)continue;auto it=data.tool_in_base_poses().find(key.pose_index);if(it==data.tool_in_base_poses().end())throw core::Exception(core::Status::InvalidState,"calibrate_hand_eye","missing paired tool pose");pairs.push_back({key.pose_index,it->second,*obs.initial_pose});}if(pairs.size()<5)throw core::Exception(core::Status::InvalidState,"calibrate_hand_eye","at least five paired poses required");std::sort(pairs.begin(),pairs.end(),[](const Pair&a,const Pair&b){return a.idx<b.idx;});
 std::vector<Pose3d>A,B;for(std::size_t i=1;i<pairs.size();++i){A.push_back(compose_pose(inverse_pose(pairs.front().t),pairs[i].t));if(data.setup_kind()==SetupKind::HandEyeMovingCamera)B.push_back(compose_pose(pairs.front().c,inverse_pose(pairs[i].c)));else B.push_back(compose_pose(inverse_pose(pairs.front().c),pairs[i].c));}
 Pose3d first,second;if(data.setup_kind()==SetupKind::HandEyeMovingCamera){first=solve_ax_xb(A,B,data.options().linear_backend);std::vector<Pose3d>ys;for(const auto&p:pairs)ys.push_back(compose_pose(p.t,compose_pose(first,p.c)));second=average_pose(ys);}else{second=solve_ax_xb(A,B,data.options().linear_backend);std::vector<Pose3d>xs;for(const auto&p:pairs)xs.push_back(compose_pose(p.c,compose_pose(inverse_pose(second),inverse_pose(p.t))));first=average_pose(xs);}
 solver::SolverSummary summary; if(method=="nonlinear"){solver::SolverProblem problem;problem.parameter_blocks.push_back({1,values(first),6,solver::ManifoldKind::PoseSE3,false,{},{}});problem.parameter_blocks.push_back({2,values(second),6,solver::ManifoldKind::PoseSE3,false,{},{}});std::uint32_t rid=1;const bool moving=data.setup_kind()==SetupKind::HandEyeMovingCamera;for(const auto&p:pairs)problem.residual_blocks.push_back({rid++,make_hand_eye_residual(moving,1,2,p.t,p.c)});auto backend=solver::make_optimizer_backend(solver::OptimizerBackendKind::BuiltinLm);const auto st=backend->solve(problem,data.options(),&summary);if(st!=core::Status::Ok&&summary.termination!=solver::SolverTermination::Converged&&summary.termination!=solver::SolverTermination::MaxIterations)throw core::Exception(core::Status::InvalidState,"calibrate_hand_eye","nonlinear hand-eye optimization failed");first=pose_of(problem.parameter_blocks[0]);second=pose_of(problem.parameter_blocks[1]);}
 double sT=0,sR=0,maxT=0,maxR=0;const bool moving=data.setup_kind()==SetupKind::HandEyeMovingCamera;for(const auto&p:pairs){Pose3d err;if(moving){auto pred=compose_pose(p.t,compose_pose(first,p.c));err=compose_pose(inverse_pose(second),pred);}else{auto pred=compose_pose(first,compose_pose(p.t,second));err=compose_pose(inverse_pose(p.c),pred);}double te=std::sqrt(err.translation.x*err.translation.x+err.translation.y*err.translation.y+err.translation.z*err.translation.z),re=rot_error(err);sT+=te*te;sR+=re*re;maxT=std::max(maxT,te);maxR=std::max(maxR,re);}double n=static_cast<double>(pairs.size());HandEyeResult result{first,second,std::sqrt(sT/n),std::sqrt(sR/n),maxT,maxR,summary};data.set_hand_eye_result(result);*errors={result.translation_rmse,result.rotation_rmse,result.translation_max,result.rotation_max};}
}
